\set ON_ERROR_STOP on

-- Backfill POSTVENTA 2026-07-31 / Script 05
-- Ejecutar despues de los scripts 01, 02, 03 y 04.
-- Objetivo: reconstruir periodos, facturas, pagos y encuestas desde POSTVENTA_ALBRU.xlsx.

BEGIN;

-- Normalizacion previa: segundo servicio real del telefono 953369543 que ya estaba
-- mezclado en un unico lead POSTVENTA historico.
WITH e AS (
    SELECT
        '953369543'::text AS lead,
        'DNI'::text AS tipo_documento,
        '46942380'::text AS documento,
        'TOMASA BRAULIA MAYHUIRE PEREZ'::text AS cliente,
        '953369543'::text AS celular_registro,
        '935082227'::text AS celular_referencia,
        'LIMA'::text AS departamento,
        'P.J VILLA HERMOSA MZ J2 LT 8'::text AS direccion,
        '2026-06-19'::date AS fecha_instalacion,
        'Duo - Fibra, DGO Hogar - 850 Mbps'::text AS plan_snapshot,
        154.90::numeric(38,2) AS precio_final
), cu AS (
    INSERT INTO contacto (prefijo, lead, nombre_conocido, created_at, updated_at)
    SELECT '+51', e.lead, e.cliente, now(), now()
    FROM e
    ON CONFLICT (prefijo, lead) DO UPDATE SET updated_at = now()
    RETURNING id, lead
), needed AS (
    SELECT e.*, cu.id AS id_contacto
    FROM e
    JOIN cu ON cu.lead = e.lead
    WHERE NOT EXISTS (
        SELECT 1
        FROM lead l
        JOIN datos_preventa dp ON dp.id = l.id_datos_preventa
        WHERE l.id_contacto = cu.id
          AND dp.numero_documento_titular_servicio = e.documento
    )
), di AS (
    INSERT INTO datos_preventa (
        tipo_documento,
        numero_documento_titular_servicio,
        nombre_titular_servicio,
        celular_registro,
        celular_referencia
    )
    SELECT tipo_documento, documento, cliente, celular_registro, celular_referencia
    FROM needed
    RETURNING id, numero_documento_titular_servicio
), dir AS (
    INSERT INTO direccion (tipo_domicilio, direccion, referencia)
    SELECT 'HOGAR', direccion, concat('Backfill POSTVENTA duplicado existente | DOC=', documento)
    FROM needed
    RETURNING id, referencia
), li AS (
    INSERT INTO lead (
        prefijo, lead, id_contacto, id_equipo, etapa, estado, base, id_campana,
        numero_documento_titular_servicio_snapshot, direccion_snapshot,
        id_datos_preventa, id_direccion, id_plan, nombre_plan_snapshot,
        nombre_proveedor_snapshot, precio_plan_snapshot, precio_adicionales_snapshot,
        precio_final, dia_corte_facturacion, meses_permanencia_snapshot,
        estado_cliente_postventa, created_at, last_entry_at, updated_at
    )
    SELECT
        '+51', n.lead, n.id_contacto, 1, 'POSTVENTA', 'GESTIONADO', 'MASIVO', NULL,
        n.documento, n.direccion, di.id, dir.id, NULL, n.plan_snapshot,
        'WIN', n.precio_final, NULL, n.precio_final, 23, 3, 'ACTIVO',
        n.fecha_instalacion::timestamp AT TIME ZONE 'America/Lima',
        n.fecha_instalacion::timestamp AT TIME ZONE 'America/Lima',
        now()
    FROM needed n
    JOIN di ON di.numero_documento_titular_servicio = n.documento
    JOIN dir ON dir.referencia = concat('Backfill POSTVENTA duplicado existente | DOC=', n.documento)
    RETURNING id, lead, nombre_plan_snapshot, precio_final
), ci AS (
    INSERT INTO calendario_facturacion_postventa (
        id_lead, fecha_instalacion, proveedor_snapshot, plan_snapshot, meses_permanencia_snapshot,
        monto_plan_snapshot, tipo_regla_proveedor, dia_corte, dia_vencimiento,
        mes_corte_base, numero_corte_base, bloque_facturacion, requiere_prorrateo_inicial,
        activo, corte_corregido, observacion, created_at, updated_at
    )
    SELECT
        li.id, '2026-06-19'::date, 'WIN', li.nombre_plan_snapshot, 3,
        li.precio_final, 'WIN', 23, 28, '2026-06-01'::date, 1, 'MISMO_MES',
        true, true, false, 'BACKFILL_POSTVENTA_20260731 | duplicado 953369543',
        now(), now()
    FROM li
    WHERE NOT EXISTS (SELECT 1 FROM calendario_facturacion_postventa c WHERE c.id_lead = li.id)
    RETURNING id, id_lead, mes_corte_base, numero_corte_base, monto_plan_snapshot
), pi AS (
    INSERT INTO periodo_facturacion_postventa (
        id_calendario_facturacion, id_lead, numero_periodo, fecha_inicio_periodo,
        fecha_fin_periodo, fecha_corte_estimada, fecha_vencimiento_estimado,
        monto_esperado, estado, observacion, created_at, updated_at
    )
    SELECT
        ci.id, ci.id_lead, 1, '2026-06-01'::date, '2026-06-28'::date,
        '2026-06-23'::date, '2026-06-28'::date, ci.monto_plan_snapshot, 'ABIERTO',
        'BACKFILL_POSTVENTA_20260731 | periodo base duplicado 953369543',
        now(), now()
    FROM ci
    WHERE NOT EXISTS (
        SELECT 1 FROM periodo_facturacion_postventa p
        WHERE p.id_lead = ci.id_lead AND p.numero_periodo = 1
    )
    RETURNING id
)
SELECT count(*) AS pre_extra_953_insertado FROM li;

WITH extra_953 AS (
    SELECT
        '953369543'::text AS lead,
        'DNI'::text AS tipo_documento,
        '46942380'::text AS documento,
        'TOMASA BRAULIA MAYHUIRE PEREZ'::text AS cliente,
        '953369543'::text AS celular_registro,
        '935082227'::text AS celular_referencia,
        'LIMA'::text AS departamento,
        'P.J VILLA HERMOSA MZ J2 LT 8'::text AS direccion,
        '2026-06-19'::date AS fecha_instalacion,
        'Duo - Fibra, DGO Hogar - 850 Mbps'::text AS plan_snapshot,
        154.90::numeric(38,2) AS precio_final
), extra_contacto AS (
    INSERT INTO contacto (prefijo, lead, nombre_conocido, created_at, updated_at)
    SELECT '+51', e.lead, e.cliente, now(), now()
    FROM extra_953 e
    ON CONFLICT (prefijo, lead) DO UPDATE SET updated_at = now()
    RETURNING id, lead
), extra_needed AS (
    SELECT e.*, c.id AS id_contacto
    FROM extra_953 e
    JOIN extra_contacto c ON c.lead = e.lead
    WHERE NOT EXISTS (
        SELECT 1
        FROM lead l
        JOIN datos_preventa dp ON dp.id = l.id_datos_preventa
        WHERE l.id_contacto = c.id
          AND dp.numero_documento_titular_servicio = e.documento
    )
), extra_datos AS (
    INSERT INTO datos_preventa (
        tipo_documento,
        numero_documento_titular_servicio,
        nombre_titular_servicio,
        celular_registro,
        celular_referencia
    )
    SELECT tipo_documento, documento, cliente, celular_registro, celular_referencia
    FROM extra_needed
    RETURNING id, numero_documento_titular_servicio
), extra_direccion AS (
    INSERT INTO direccion (tipo_domicilio, direccion, referencia)
    SELECT 'HOGAR', direccion, concat('Backfill POSTVENTA duplicado existente | DOC=', documento)
    FROM extra_needed
    RETURNING id, referencia
), extra_prepared AS (
    SELECT e.*, dp.id AS id_datos_preventa, di.id AS id_direccion
    FROM extra_needed e
    JOIN extra_datos dp ON dp.numero_documento_titular_servicio = e.documento
    JOIN extra_direccion di ON di.referencia = concat('Backfill POSTVENTA duplicado existente | DOC=', e.documento)
), extra_lead AS (
    INSERT INTO lead (
        prefijo, lead, id_contacto, id_equipo, etapa, estado, base, id_campana,
        numero_documento_titular_servicio_snapshot, direccion_snapshot,
        id_datos_preventa, id_direccion, id_plan, nombre_plan_snapshot,
        nombre_proveedor_snapshot, precio_plan_snapshot, precio_adicionales_snapshot,
        precio_final, dia_corte_facturacion, meses_permanencia_snapshot,
        estado_cliente_postventa, created_at, last_entry_at, updated_at
    )
    SELECT
        '+51', lead, id_contacto, 1, 'POSTVENTA', 'GESTIONADO', 'MASIVO', NULL,
        documento, direccion, id_datos_preventa, id_direccion, NULL, plan_snapshot,
        'WIN', precio_final, NULL, precio_final, 23, 3, 'ACTIVO',
        fecha_instalacion::timestamp AT TIME ZONE 'America/Lima',
        fecha_instalacion::timestamp AT TIME ZONE 'America/Lima',
        now()
    FROM extra_prepared
    RETURNING id, lead
) SELECT count(*) AS extra_953_insertado FROM extra_lead;

CREATE TEMP TABLE tmp_postventa_metrics (
    metric text PRIMARY KEY,
    value integer NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE tmp_postventa_lead_src (
    id_lead_bd bigint,
    lead text NOT NULL,
    documento text NOT NULL,
    cliente text,
    hoja_postventa text NOT NULL,
    fila_postventa integer NOT NULL,
    corte_postventa integer NOT NULL,
    max_periodo_esperado integer NOT NULL,
    usar_id_directo boolean NOT NULL,
    lead_unico boolean NOT NULL
) ON COMMIT DROP;

INSERT INTO tmp_postventa_lead_src (
