INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'periodos_fuente', count(*) FROM tmp_postventa_period_src;

CREATE TEMP TABLE tmp_postventa_lead_match AS
SELECT
    s.*,
    l.id AS id_lead
FROM tmp_postventa_lead_src s
JOIN lead l ON (
    (s.usar_id_directo AND l.id = s.id_lead_bd)
    OR (
        NOT s.usar_id_directo
        AND regexp_replace(coalesce(l.lead, ''), '\D', '', 'g') = s.lead
        AND (
            NULLIF(l.numero_documento_titular_servicio_snapshot, '') = s.documento
            OR EXISTS (
                SELECT 1
                FROM datos_preventa dpx
                WHERE dpx.id = l.id_datos_preventa
                  AND NULLIF(dpx.numero_documento_titular_servicio, '') = s.documento
            )
        )
    )
)
LEFT JOIN datos_preventa dp ON dp.id = l.id_datos_preventa
WHERE s.usar_id_directo
   OR NULLIF(dp.numero_documento_titular_servicio, '') = s.documento
   OR NULLIF(l.numero_documento_titular_servicio_snapshot, '') = s.documento;

CREATE INDEX idx_tmp_postventa_lead_match_row ON tmp_postventa_lead_match(hoja_postventa, fila_postventa, lead, documento);
CREATE INDEX idx_tmp_postventa_lead_match_id ON tmp_postventa_lead_match(id_lead);

INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'leads_encontrados', count(*) FROM tmp_postventa_lead_match;

DO $$
DECLARE
    v_no_match integer;
    v_multi_match integer;
BEGIN
    SELECT count(*) INTO v_no_match
    FROM tmp_postventa_lead_src s
    WHERE NOT EXISTS (
        SELECT 1
        FROM tmp_postventa_lead_match lm
        WHERE lm.hoja_postventa = s.hoja_postventa
          AND lm.fila_postventa = s.fila_postventa
          AND lm.lead = s.lead
          AND lm.documento = s.documento
    );

    SELECT count(*) INTO v_multi_match
    FROM (
        SELECT hoja_postventa, fila_postventa, lead, documento, count(DISTINCT id_lead) AS matches
        FROM tmp_postventa_lead_match
        GROUP BY hoja_postventa, fila_postventa, lead, documento
        HAVING count(DISTINCT id_lead) <> 1
    ) x;

    IF v_no_match > 0 OR v_multi_match > 0 THEN
        RAISE EXCEPTION 'Backfill POSTVENTA abortado: leads sin match=%, leads con match ambiguo=%', v_no_match, v_multi_match;
    END IF;
END $$;

CREATE TEMP TABLE tmp_postventa_period_match_base AS
SELECT
    ps.*,
    lm.id_lead,
    c.id AS id_calendario,
    c.mes_corte_base,
    c.numero_corte_base,
    c.monto_plan_snapshot
FROM tmp_postventa_period_src ps
JOIN tmp_postventa_lead_match lm ON lm.lead = ps.lead AND lm.documento = ps.documento
JOIN calendario_facturacion_postventa c ON c.id_lead = lm.id_lead;

CREATE INDEX idx_tmp_postventa_period_match ON tmp_postventa_period_match_base(id_lead, numero_periodo);

WITH period_insert AS (
    INSERT INTO periodo_facturacion_postventa (
        id_calendario_facturacion,
        id_lead,
        numero_periodo,
        fecha_inicio_periodo,
        fecha_fin_periodo,
        fecha_corte_estimada,
        fecha_vencimiento_estimado,
        monto_esperado,
        estado,
        observacion,
        created_at,
        updated_at
    )
    SELECT
        p.id_calendario,
        p.id_lead,
        p.numero_periodo,
        CASE
            WHEN p.numero_periodo = 1 AND p.numero_corte_base = 2 THEN p.mes_corte_base + interval '22 days'
            WHEN p.numero_periodo = 1 THEN p.mes_corte_base
            ELSE (
                CASE WHEN p.numero_corte_base = 2 THEN p.mes_corte_base + interval '1 month' + interval '27 days'
                     ELSE p.mes_corte_base + interval '27 days' END
                + ((p.numero_periodo - 2) || ' months')::interval
                + interval '1 day'
            )
        END::date,
        (
            CASE WHEN p.numero_corte_base = 2 THEN p.mes_corte_base + interval '1 month' + interval '27 days'
                 ELSE p.mes_corte_base + interval '27 days' END
            + ((p.numero_periodo - 1) || ' months')::interval
        )::date,
        (date_trunc('month', (
            CASE WHEN p.numero_corte_base = 2 THEN p.mes_corte_base + interval '1 month' + interval '27 days'
                 ELSE p.mes_corte_base + interval '27 days' END
            + ((p.numero_periodo - 1) || ' months')::interval
        )) + interval '22 days')::date,
        (
            CASE WHEN p.numero_corte_base = 2 THEN p.mes_corte_base + interval '1 month' + interval '27 days'
                 ELSE p.mes_corte_base + interval '27 days' END
            + ((p.numero_periodo - 1) || ' months')::interval
        )::date,
        p.monto_plan_snapshot,
        'ABIERTO',
        concat('BACKFILL_POSTVENTA_20260731 | periodo ', p.numero_periodo, ' desde Excel ', p.hoja_postventa, ' fila ', p.fila_postventa),
        now(),
        now()
    FROM tmp_postventa_period_match_base p
    WHERE NOT EXISTS (
        SELECT 1
        FROM periodo_facturacion_postventa px
        WHERE px.id_lead = p.id_lead AND px.numero_periodo = p.numero_periodo
    )
    RETURNING id
)
INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'periodos_insertados', count(*) FROM period_insert;

CREATE TEMP TABLE tmp_postventa_period_resolved AS
SELECT
    p.*,
    pf.id AS id_periodo
FROM tmp_postventa_period_match_base p
JOIN periodo_facturacion_postventa pf
    ON pf.id_lead = p.id_lead AND pf.numero_periodo = p.numero_periodo;

CREATE INDEX idx_tmp_postventa_period_resolved_id ON tmp_postventa_period_resolved(id_periodo);
CREATE INDEX idx_tmp_postventa_period_resolved_lead ON tmp_postventa_period_resolved(id_lead, numero_periodo);

WITH period_update AS (
    UPDATE periodo_facturacion_postventa pf
    SET
        fecha_emision_confirmada = pr.fecha_emision_confirmada,
        fecha_vencimiento_confirmado = pr.fecha_vencimiento_confirmado,
        monto_facturado = pr.monto_facturado,
        estado = CASE
            WHEN pr.estado_periodo = 'ABIERTO'
              AND (
                  pf.estado IN ('CERRADO_PAGO_CLIENTE', 'CERRADO_PAGO_EMPRESA')
                  OR EXISTS (
                      SELECT 1
                      FROM pago_postventa pp
                      WHERE pp.id_periodo_facturacion = pf.id
                        AND pp.estado IN ('PAGADO_CLIENTE', 'PAGADO_EMPRESA')
                  )
              )
            THEN pf.estado
            ELSE pr.estado_periodo
        END,
        observacion = concat('BACKFILL_POSTVENTA_20260731 | ', pr.hoja_postventa, ' fila ', pr.fila_postventa),
        updated_at = now()
    FROM tmp_postventa_period_resolved pr
    WHERE pf.id = pr.id_periodo
    RETURNING pf.id, pf.id_lead, pf.numero_periodo, pf.estado
)
INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'periodos_actualizados', count(*) FROM period_update;

WITH pago_insert AS (
    INSERT INTO pago_postventa (
        id_lead,
        id_periodo_facturacion,
        aportante,
        estado,
        monto,
        fecha_pago,
        condicion,
        observacion,
        created_at,
        updated_at
    )
    SELECT
        pr.id_lead,
        pr.id_periodo,
        pr.aportante,
        pr.estado_pago,
        coalesce(pr.monto_pago, pr.monto_facturado),
        pr.fecha_pago,
        pr.condicion_pago,
        concat('BACKFILL_POSTVENTA_20260731 | pago Excel ', pr.hoja_postventa, ' fila ', pr.fila_postventa),
        now(),
        now()
    FROM tmp_postventa_period_resolved pr
    WHERE pr.estado_pago IS NOT NULL
      AND NOT EXISTS (
          SELECT 1
          FROM pago_postventa pp
          WHERE pp.id_periodo_facturacion = pr.id_periodo
            AND pp.estado = pr.estado_pago
            AND pp.fecha_pago = pr.fecha_pago
      )
    RETURNING id
)
INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'pagos_insertados', count(*) FROM pago_insert;

