CREATE TEMP TABLE tmp_postventa_survey_resolved AS
SELECT
    ss.*,
    lm.id_lead,
    pf.id AS id_periodo,
    CASE WHEN ss.calificacion IS NULL THEN 'OMITIDA' ELSE 'REALIZADA' END AS estado_encuesta,
    CASE WHEN ss.calificacion IS NULL THEN NULL
         WHEN ss.calificacion <= 4 THEN 'MALO'
         WHEN ss.calificacion <= 6 THEN 'REGULAR'
         WHEN ss.calificacion <= 8 THEN 'BUENO'
         ELSE 'EXCELENTE' END AS status_encuesta
FROM tmp_postventa_survey_src ss
JOIN tmp_postventa_lead_match lm ON lm.lead = ss.lead AND lm.documento = ss.documento
JOIN periodo_facturacion_postventa pf ON pf.id_lead = lm.id_lead AND pf.numero_periodo = ss.numero_periodo;

CREATE INDEX idx_tmp_postventa_survey_resolved ON tmp_postventa_survey_resolved(id_lead, numero_periodo, tipo_encuesta);

WITH encuesta_update AS (
    UPDATE encuesta_postventa e
    SET
        id_periodo_facturacion = sr.id_periodo,
        tipo_encuesta = sr.tipo_encuesta,
        tipo_contacto = NULLIF(sr.tipo_contacto, ''),
        calificacion = sr.calificacion,
        status = sr.status_encuesta,
        estado = sr.estado_encuesta,
        prioridad = 'NORMAL',
        fecha_realizada = CASE WHEN sr.calificacion IS NULL THEN NULL ELSE now() AT TIME ZONE 'America/Lima' END,
        updated_at = now()
    FROM tmp_postventa_survey_resolved sr
    WHERE e.id_lead = sr.id_lead
      AND e.numero_encuesta = sr.numero_periodo
      AND e.tipo_encuesta = sr.tipo_encuesta
    RETURNING e.id
)
INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'encuestas_actualizadas', count(*) FROM encuesta_update;

WITH encuesta_insert AS (
    INSERT INTO encuesta_postventa (
        id_lead,
        id_periodo_facturacion,
        tipo_encuesta,
        tipo_contacto,
        calificacion,
        status,
        estado,
        prioridad,
        fecha_programada,
        fecha_limite,
        fecha_realizada,
        numero_encuesta,
        created_at,
        updated_at
    )
    SELECT
        sr.id_lead,
        sr.id_periodo,
        sr.tipo_encuesta,
        NULLIF(sr.tipo_contacto, ''),
        sr.calificacion,
        sr.status_encuesta,
        sr.estado_encuesta,
        'NORMAL',
        now() AT TIME ZONE 'America/Lima',
        (now() AT TIME ZONE 'America/Lima') + interval '48 hours',
        CASE WHEN sr.calificacion IS NULL THEN NULL ELSE now() AT TIME ZONE 'America/Lima' END,
        sr.numero_periodo,
        now(),
        now()
    FROM tmp_postventa_survey_resolved sr
    WHERE NOT EXISTS (
        SELECT 1
        FROM encuesta_postventa e
        WHERE e.id_lead = sr.id_lead
          AND e.numero_encuesta = sr.numero_periodo
          AND e.tipo_encuesta = sr.tipo_encuesta
    )
    RETURNING id
)
INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'encuestas_insertadas', count(*) FROM encuesta_insert;

CREATE TEMP TABLE tmp_postventa_lead_final AS
SELECT
    lm.id_lead,
    bool_or(p.estado IN ('CERRADO_BAJA', 'CERRADO_BAJA_ADEUDO')) AS tiene_baja,
    bool_or(p.numero_periodo = 3 AND p.estado IN ('CERRADO_PAGO_CLIENTE', 'CERRADO_PAGO_EMPRESA')) AS completo_permanencia,
    max(p.numero_periodo) FILTER (WHERE p.estado IN ('CERRADO_PAGO_EMPRESA')) AS ultimo_pago_empresa
FROM tmp_postventa_lead_match lm
JOIN periodo_facturacion_postventa p ON p.id_lead = lm.id_lead
GROUP BY lm.id_lead;

WITH lead_update AS (
    UPDATE lead l
    SET
        etapa = CASE WHEN lf.completo_permanencia AND NOT lf.tiene_baja THEN 'COBRANZA' ELSE 'POSTVENTA' END,
        estado = CASE WHEN lf.completo_permanencia AND NOT lf.tiene_baja THEN 'NUEVO' ELSE l.estado END,
        id_asesor_asignado = NULL,
        nombre_asesor_asignado = NULL,
        id_tipificacion = CASE WHEN lf.completo_permanencia AND NOT lf.tiene_baja THEN NULL ELSE l.id_tipificacion END,
        codigo_tipificacion = CASE WHEN lf.completo_permanencia AND NOT lf.tiene_baja THEN NULL ELSE l.codigo_tipificacion END,
        id_subtipificacion = CASE WHEN lf.completo_permanencia AND NOT lf.tiene_baja THEN NULL ELSE l.id_subtipificacion END,
        codigo_subtipificacion = CASE WHEN lf.completo_permanencia AND NOT lf.tiene_baja THEN NULL ELSE l.codigo_subtipificacion END,
        estado_cliente_postventa = CASE
            WHEN lf.tiene_baja THEN 'BAJA'
            WHEN l.estado_cliente_postventa = 'SUSPENDIDO' THEN 'SUSPENDIDO'
            WHEN lf.completo_permanencia THEN 'ACTIVO'
            WHEN lf.ultimo_pago_empresa IS NOT NULL THEN 'SUSPENDIDO'
            ELSE 'ACTIVO'
        END,
        updated_at = now()
    FROM tmp_postventa_lead_final lf
    WHERE l.id = lf.id_lead
    RETURNING l.id
)
INSERT INTO tmp_postventa_metrics(metric, value)
SELECT 'leads_estado_actualizado', count(*) FROM lead_update;

DO $$
DECLARE
    v_multi_abierto integer;
    v_pago_abierto integer;
BEGIN
    SELECT count(*) INTO v_multi_abierto
    FROM (
        SELECT p.id_lead
        FROM periodo_facturacion_postventa p
        JOIN tmp_postventa_lead_match lm ON lm.id_lead = p.id_lead
        WHERE p.estado = 'ABIERTO'
        GROUP BY p.id_lead
        HAVING count(*) > 1
    ) x;

    SELECT count(*) INTO v_pago_abierto
    FROM periodo_facturacion_postventa p
    JOIN tmp_postventa_lead_match lm ON lm.id_lead = p.id_lead
    JOIN pago_postventa pp ON pp.id_periodo_facturacion = p.id
    WHERE p.estado = 'ABIERTO';

    IF v_multi_abierto > 0 OR v_pago_abierto > 0 THEN
        RAISE EXCEPTION 'Backfill POSTVENTA incoherente: leads con mas de un periodo abierto=%, pagos en periodo abierto=%', v_multi_abierto, v_pago_abierto;
    END IF;
END $$;

WITH validation_count AS (
    SELECT
        count(DISTINCT s.hoja_postventa || ':' || s.fila_postventa || ':' || s.lead || ':' || s.documento) AS leads_validados_710
    FROM tmp_postventa_lead_src s
    JOIN lead l ON (
        (s.usar_id_directo AND l.id = s.id_lead_bd)
        OR (
            NOT s.usar_id_directo
            AND regexp_replace(coalesce(l.lead, ''), '\D', '', 'g') = s.lead
            AND (
                NULLIF(l.numero_documento_titular_servicio_snapshot, '') = s.documento
                OR EXISTS (
                    SELECT 1
                    FROM datos_preventa dpx
                    WHERE dpx.id = l.id_datos_preventa
                      AND NULLIF(dpx.numero_documento_titular_servicio, '') = s.documento
                )
            )
        )
    )
    LEFT JOIN datos_preventa dp ON dp.id = l.id_datos_preventa
    WHERE (s.usar_id_directo
        OR NULLIF(dp.numero_documento_titular_servicio, '') = s.documento
        OR NULLIF(dp.numero_documento_titular_servicio, '') = s.documento
        OR NULLIF(l.numero_documento_titular_servicio_snapshot, '') = s.documento)
      AND l.etapa IN ('POSTVENTA', 'COBRANZA')
), unmatched_sample AS (
    SELECT
        string_agg(concat(s.hoja_postventa, ':', s.fila_postventa, ':', s.lead, ':', s.documento, ':id=', coalesce(s.id_lead_bd::text, 'NULL'), ':unico=', s.lead_unico::text), ' | ') AS muestra
    FROM (
        SELECT s.*
        FROM tmp_postventa_lead_src s
        WHERE NOT EXISTS (
            SELECT 1
            FROM tmp_postventa_lead_match lm
            WHERE lm.lead = s.lead
              AND lm.documento = s.documento
              AND lm.fila_postventa = s.fila_postventa
        )
        LIMIT 12
    ) s
)
SELECT
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'fuente_leads_710') AS fuente_leads_710,
    (SELECT count(*) FROM tmp_postventa_lead_src WHERE usar_id_directo) AS fuente_match_por_id,
    (SELECT count(*) FROM tmp_postventa_lead_src s JOIN lead l ON s.usar_id_directo AND l.id = s.id_lead_bd) AS encontrados_por_id_directo,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'leads_encontrados') AS leads_encontrados,
    (
        SELECT count(*)
        FROM lead l
        LEFT JOIN datos_preventa dp ON dp.id = l.id_datos_preventa
        WHERE regexp_replace(coalesce(l.lead, ''), '\D', '', 'g') = '953369543'
          AND (
              NULLIF(l.numero_documento_titular_servicio_snapshot, '') = '46942380'
              OR NULLIF(dp.numero_documento_titular_servicio, '') = '46942380'
          )
    ) AS leads_extra_953_presentes,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'periodos_fuente') AS periodos_fuente,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'periodos_insertados') AS periodos_insertados,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'periodos_actualizados') AS periodos_actualizados,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'pagos_insertados') AS pagos_insertados,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'encuestas_actualizadas') AS encuestas_actualizadas,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'encuestas_insertadas') AS encuestas_insertadas,
    (SELECT value FROM tmp_postventa_metrics WHERE metric = 'leads_estado_actualizado') AS leads_estado_actualizado,
    (SELECT leads_validados_710 FROM validation_count) AS leads_validados_710,
    (SELECT muestra FROM unmatched_sample) AS muestra_no_encontrados;

COMMIT;
